sds sdstrim(sds s, const char *cset) {
    char *end, *sp, *ep;
    size_t len;

    len = sdslen(s);
    if (len == 0) {
        s[0] = '\0';
        sdssetlen(s, 0);
        return s;
    }

    sp = s;
    ep = end = s + len - 1;
    while (sp <= end && strchr(cset, *sp)) sp++;
    while (ep > sp && strchr(cset, *ep)) ep--;
    len = (sp > ep) ? 0 : (size_t)((ep - sp) + 1);
    if (s != sp) memmove(s, sp, len);
    s[len] = '\0';
    sdssetlen(s, len);
    return s;
}
