static double parse_number(state *s) {

    const char *p = s->next;
    double value = 0.0;

    if (p[0] == '0' && (p[1] == 'x' || p[1] == 'X') &&
        isxdigit((unsigned char)p[2])) {
        p += 2;
        while (isxdigit((unsigned char)p[0])) {
            const char c = p[0];
            const int d = isdigit((unsigned char)c) ? c - '0' :
                          (c >= 'a' ? c - 'a' + 10 : c - 'A' + 10);
            value = value * 16.0 + d;
            p++;
        }
    } else {
        int exponent = 0, digits = 0;

        while (isdigit((unsigned char)p[0])) {
            value = value * 10.0 + (p[0] - '0');
            p++; digits++;
        }

        if (p[0] == '.') {
            p++;
            while (isdigit((unsigned char)p[0])) {
                value = value * 10.0 + (p[0] - '0');
                p++; digits++; exponent--;
            }
        }

        if (digits == 0) {

            s->type = TOK_ERROR;
            return 0.0;
        }

        if (p[0] == 'e' || p[0] == 'E') {

            const char *ep = p + 1;
            int esign = 1, e = 0;

            if (ep[0] == '+') {
                ep++;
            } else if (ep[0] == '-') {
                esign = -1;
                ep++;
            }

            if (isdigit((unsigned char)ep[0])) {
                while (isdigit((unsigned char)ep[0])) {
                    if (e < 100000000) e = e * 10 + (ep[0] - '0');
                    ep++;
                }
                exponent += esign * e;
                p = ep;
            }
        }

        if (exponent && value != 0.0) {
            if (exponent < 0 && exponent >= -22) {
                value /= exact_pow10[-exponent];
            } else {
                value *= pow(10.0, exponent);
            }
        }
    }

    s->type = TOK_NUMBER;
    s->next = p;
    return value;
}
