static void optimize(te_expr *n) {

    if (!IS_PURE(n->type)) return;

    const int arity = ARITY(n->type);
    int known = 1, i;
    for (i = 0; i < arity; ++i) {
        optimize((te_expr*)(n->parameters[i]));
        if (((te_expr*)(n->parameters[i]))->type != TE_CONSTANT) known = 0;
