te_expr *te_compile(const char *expression, const te_variable *variables, int var_count, int *error) {
    state s;
    s.next = expression;
    s.lookup = variables;
    s.lookup_len = var_count;
    s.applied_unary = 0;
    s.depth = 0;

    next_token(&s);
    te_expr *root = binary(&s, PREC_LIST);
    if (root == NULL) {
        if (error) *error = -1;
        return NULL;
    }

    if (s.type != TOK_END) {
        te_free(root);
        if (error) {
            *error = s.next - expression;
            if (*error == 0) *error = 1;
        }
        return NULL;
    }

    optimize(root);
    if (error) *error = 0;
    return root;
}
